import { Mesh, PlaneGeometry, Group, Color, Vector3, Euler } from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
  color,
  mix,
  vec4,
  float,
  positionNormalNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createMSDFMaterial } from '@/text';
import { NodeConfig, NodeContext } from '@/primitives';

export default function createNode(config: NodeConfig, ctx: NodeContext): Group {
  // --- Geometry --------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);

  // --- Base texture -----------------------------------------------------------
  const baseTex = ctx.textureLoader(config.assets?.imageUrl);
  const baseMaterial = new MeshBasicNodeMaterial({
    map: texture(baseTex),
    side: THREE.DoubleSide,
  });

  const baseMesh = new Mesh(geometry, baseMaterial);
  baseMesh.castShadow = false;
  baseMesh.receiveShadow = false;

  // --- Text rendering ---------------------------------------------------------
  const text = config.textContent?.[0]?.text ?? '';
  // Default to accent color for CTA label
  const textColor = new Color(config.colors?.accent ?? '#ff2a38');

  // Assume createMSDFMaterial returns a MeshBasicNodeMaterial using the font atlas
  const textMaterial = createMSDFMaterial(text, ctx.fontAtlas, {
    color: textColor,
    size: config.typography?.text?.size ?? 0.13,
  });

  const textMesh = new Mesh(geometry, textMaterial);
  // Slight offset to avoid Z‑fighting with the base plane
  textMesh.position.z = 0.001;
  textMesh.castShadow = false;
  textMesh.receiveShadow = false;

  // --- Group assembly ---------------------------------------------------------
  const group = new Group();
  group.add(baseMesh);
  group.add(textMesh);

  // Apply placement
  if (config.position) {
    group.position.set(...config.position);
  }
  if (config.rotation) {
    group.rotation.set(...config.rotation);
  }
  if (config.scale) {
    group.scale.set(...config.scale);
  }

  // --- Event handlers placeholder ---------------------------------------------
  group.userData.handlers = {};

  // --- Cleanup ---------------------------------------------------------------
  const timelines: gsap.core.Animation[] = [];

  group.userData.cleanup = () => {
    // Dispose geometry (shared)
    geometry.dispose();

    // Dispose materials (do not dispose textures; they are managed by the context)
    baseMaterial.dispose();
    textMaterial.dispose();

    // Kill any GSAP timelines that might have been created elsewhere
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
  };

  // --- Apply cinematic primitives if any -------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === 'function') {
        fn(group, primitive.params);
      }
    }
  }

  return group;
}
